cuda_source = """
#include <cuda_fp16.h>

__global__ void cumulative_product_kernel(
    const half* input,
    half* output,
    int64_t total_elements,
    int64_t dim_size,
    int64_t stride
) {
    int64_t tid = blockIdx.x * blockDim.x + threadIdx.x;

    if (tid >= total_elements) return;

    // Calculate which element we're processing
    int64_t batch_idx = tid / stride;
    int64_t dim_idx = tid % dim_size;

    // For each batch, compute cumulative product along the specified dimension
    half* batch_output = output + batch_idx * stride;
    const half* batch_input = input + batch_idx * stride;

    // Initialize with first element
    batch_output[dim_idx] = batch_input[dim_idx];

    // Compute cumulative product from left to right
    for (int64_t i = 1; i <= dim_idx; i++) {
        batch_output[dim_idx] *= batch_output[dim_idx - i];
    }
}

__global__ void cumulative_product_kernel_v2(
    const half* input,
    half* output,
    int64_t total_elements,
    int64_t dim_size,
    int64_t stride
) {
    int64_t tid = blockIdx.x * blockDim.x + threadIdx.x;

    if (tid >= total_elements) return;

    // Calculate which batch and position we're processing
    int64_t batch_idx = tid / stride;
    int64_t dim_idx = tid % dim_size;

    // For each batch, compute cumulative product along the specified dimension
    half* batch_output = output + batch_idx * stride;
    const half* batch_input = input + batch_idx * stride;

    // Process elements sequentially for cumulative product
    if (dim_idx == 0) {
        batch_output[0] = batch_input[0];
    } else {
        batch_output[dim_idx] = batch_output[dim_idx - 1] * batch_input[dim_idx];
    }
}
"""

# Alternative approach that works better with shared memory
cuda_source_optimized = """
#include <cuda_fp16.h>

__global__ void cumulative_product_kernel_optimized(
    const half* input,
    half* output,
    int64_t total_elements,
    int64_t dim_size,
    int64_t stride
) {
    int64_t batch_idx = blockIdx.x;
    int64_t tid = threadIdx.x;

    if (batch_idx >= total_elements / stride) return;

    // Process one batch at a time
    half* batch_output = output + batch_idx * stride;
    const half* batch_input = input + batch_idx * stride;

    // Handle first element
    if (tid == 0) {
        batch_output[0] = batch_input[0];
    }

    __syncthreads();

    // Compute cumulative product in parallel
    for (int64_t i = 1; i < dim_size; i <<= 1) {
        if (tid >= i) {
            batch_output[tid] *= batch_output[tid - i];
        }
        __syncthreads();
    }
}
"""

