    name="cumulative_product_cuda",
    cpp_sources=[],
    cuda_sources=cuda_source_optimized,
    functions=["cumulative_product_kernel_optimized"],
    verbose=True
)

class ModelNew(torch.nn.Module):
    def __init__(self, dim):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x):
        # Get input properties
        input_shape = x.shape
        total_elements = x.numel()

        # Determine stride and dimension size based on dim
        stride = 1
        dim_size = input_shape[self.dim]

        # Calculate stride for the specified dimension
        for i in range(self.dim + 1, len(input_shape)):
            stride *= input_shape[i]

        # Create output tensor
        output = torch.empty_like(x)

        # Launch kernel
        if self.dim == 1:
            batch_count = total_elements // dim_size
            threads_per_block = 256
            blocks = (batch_count + threads_per_block - 1) // threads_per_block

            module.cumulative_product_kernel_optimized(
                x.contiguous(),
                output,
                total_elements,
                dim_size,
                stride
            )
        else:
            # Fall back to pytorch implementation for other dimensions
            return torch.cumprod(x, dim=self.dim)

        return output
